"""Essential Eight (Nov 2023) <-> SCF 2025.2.2, generated by `tools/build_essential_eight_scf_mapping.py`.

SCF is the pivot: through it, an Essential Eight audit maps to ISO 27001 and back.
"""

from pathlib import Path

import pytest
import yaml
from core.mappings.engine import MappingEngine
from core.models import LoadedLibrary, RequirementNode, StoredLibrary

LIBRARIES_DIR = Path(__file__).resolve().parents[2] / "library" / "libraries"
MAPPING = "mapping-essential-eight-2023-and-scf-2025.2.2"
E8 = "urn:intuitem:risk:framework:essential-eight-2023"
SCF = "urn:intuitem:risk:framework:scf-2025.2.2"
ISO = "urn:intuitem:risk:framework:iso27001-2022"


def load(ref_id):
    urn = f"urn:intuitem:risk:library:{ref_id}"
    if not LoadedLibrary.objects.filter(urn=urn).exists():
        stored = StoredLibrary.objects.filter(urn=urn).first()
        if stored is None:
            content = (LIBRARIES_DIR / f"{ref_id}.yaml").read_bytes()
            stored, error = StoredLibrary.store_library_content(content)
            assert error is None, f"could not store {ref_id}: {error}"
        assert stored.load() is None


@pytest.fixture
def libraries(db):
    for ref_id in ("essential-eight-2023", "scf-2025.2.2", "iso27001-2022"):
        load(ref_id)
    for ref_id in (MAPPING, "mapping-iso27001-2022-and-scf-2025.2.2"):
        load(ref_id)


def audit(framework_urn, result="compliant"):
    nodes = RequirementNode.objects.filter(
        framework__urn=framework_urn, assessable=True
    )
    return {
        "min_score": 0,
        "max_score": 100,
        "requirement_assessments": {
            n.urn: {
                "result": result,
                "name": n.ref_id,
                "id": str(n.id),
                "source_framework": {},
            }
            for n in nodes
        },
    }


@pytest.mark.django_db
class TestEssentialEightScfMapping:
    def test_mapping_links_existing_requirements(self, libraries):
        content = yaml.safe_load((LIBRARIES_DIR / f"{MAPPING}.yaml").read_text())
        forward, back = content["objects"]["requirement_mapping_sets"]
        rows = forward["requirement_mappings"]
        urns = {r["source_requirement_urn"] for r in rows} | {
            r["target_requirement_urn"] for r in rows
        }
        assert urns == set(
            RequirementNode.objects.filter(urn__in=urns).values_list("urn", flat=True)
        )
        assert len({r["source_requirement_urn"] for r in rows}) == 150
        assert len(back["requirement_mappings"]) == len(rows)

    @pytest.mark.parametrize("source,dest", [(E8, ISO), (ISO, E8)])
    def test_scf_pivots_between_essential_eight_and_iso27001(
        self, libraries, source, dest
    ):
        inferences, path = MappingEngine().best_mapping_inferences(
            audit(source), source, dest
        )
        assert path == [source, SCF, dest]
        mapped = inferences["requirement_assessments"]
        assert mapped
        assert {RequirementNode.objects.get(urn=u).framework.urn for u in mapped} == {
            dest
        }
